Clean code, DRY - KISS - YAGNI.ejemplo:
// Violación YAGNI/KISS vs directo
// Mal: AbstractDiscountStrategyFactoryBuilder para 1 cupón
// Bien:
function applyDiscount(total: number, rate: number): number {
  if (rate <= 0 || rate >= 1) throw new RangeError("Invalid rate");
  return Number((total * (1 - rate)).toFixed(2));
}

